import React, { useMemo, useState, useEffect } from 'react';
import { Account, UserPlan } from '../types';
import { TrendingUp, PieChart as PieChartIcon, DollarSign, Calculator, Building, Landmark, Percent, Heart, Briefcase, ArrowUpRight, Target, Zap, Sliders } from 'lucide-react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, AreaChart, Area, XAxis, YAxis, CartesianGrid } from 'recharts';

interface InvestmentProps {
  accounts: Account[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
}

const COLORS = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#3b82f6', '#8b5cf6', '#06b6d4', '#f43f5e'];

const Investment: React.FC<InvestmentProps> = ({ accounts, formatCurrency, userPlan }) => {
  // Calculator State
  const [activeCalc, setActiveCalc] = useState<'compound' | 'ira' | 'insurance' | 'pension' | 'real_estate' | 'roi'>('compound');

  // Projection State
  const [projRate, setProjRate] = useState(8);
  const [projContrib, setProjContrib] = useState(500);

  // Compound Input
  const [compP, setCompP] = useState(0);
  const [compR, setCompR] = useState(7);
  const [compT, setCompT] = useState(10);
  const [compN, setCompN] = useState(12);

  // IRA Input
  const [iraPV, setIraPV] = useState(0);
  const [iraC, setIraC] = useState(6000);
  const [iraR, setIraR] = useState(7);
  const [iraT, setIraT] = useState(25);

  // Insurance Input
  const [insIncome, setInsIncome] = useState(0);
  const [insYears, setInsYears] = useState(10);
  const [insDebt, setInsDebt] = useState(0);
  const [insHealth, setInsHealth] = useState<'excellent' | 'average' | 'poor'>('average');
  const [insTerm, setInsTerm] = useState(20);

  // Pension Input
  const [penP0, setPenP0] = useState(0);
  const [penC, setPenC] = useState(0);
  const [penR, setPenR] = useState(5);
  const [penN, setPenN] = useState(20);
  const [penDrawN, setPenDrawN] = useState(240); 
  const [penDrawI, setPenDrawI] = useState(4); 

  // Real Estate Input
  const [reRent, setReRent] = useState(0);
  const [rePrice, setRePrice] = useState(0);

  // ROI Input
  const [roiInitial, setRoiInitial] = useState(0);
  const [roiFinal, setRoiFinal] = useState(0);
  const [roiCosts, setRoiCosts] = useState(0);

  const investmentAccounts = useMemo(() => {
    return accounts.filter(a => a.type === 'Investment');
  }, [accounts]);

  const totalPortfolioValue = useMemo(() => {
    return investmentAccounts.reduce((acc, curr) => acc + curr.balance, 0);
  }, [investmentAccounts]);

  // Auto-fill calculator with actual data on load
  useEffect(() => {
      if (totalPortfolioValue > 0 && compP === 0) {
          setCompP(totalPortfolioValue);
      }
  }, [totalPortfolioValue]);

  const allocationData = useMemo(() => {
      if (investmentAccounts.length === 0) return [];
      return investmentAccounts.map(acc => ({
          name: acc.name,
          value: acc.balance
      })).sort((a, b) => b.value - a.value);
  }, [investmentAccounts]);

  // Projection Logic
  const projectionData = useMemo(() => {
      const data = [];
      let currentBalance = totalPortfolioValue;
      const years = 30;
      const r = projRate / 100;

      for (let i = 0; i <= years; i++) {
          data.push({
              year: new Date().getFullYear() + i,
              value: Math.round(currentBalance),
              invested: totalPortfolioValue + (projContrib * 12 * i)
          });
          // Add annual contribution + growth
          currentBalance = (currentBalance + (projContrib * 12)) * (1 + r);
      }
      return data;
  }, [totalPortfolioValue, projRate, projContrib]);

  // Logic Implementations
  const compoundResult = useMemo(() => {
      if (compP === 0) return 0;
      const rDec = compR / 100;
      return compP * Math.pow((1 + rDec/compN), (compN * compT));
  }, [compP, compR, compN, compT]);

  const iraResult = useMemo(() => {
      if (iraPV === 0 && iraC === 0) return 0;
      const rDec = iraR / 100;
      const term1 = iraPV * Math.pow((1 + rDec), iraT);
      const term2 = rDec > 0 ? iraC * ((Math.pow((1 + rDec), iraT) - 1) / rDec) : iraC * iraT;
      return term1 + term2;
  }, [iraPV, iraR, iraC, iraT]);

  const insuranceResult = useMemo(() => {
      const coverage = (insIncome * insYears) + insDebt;
      let baseRate = (coverage / 1000) * 0.5;
      if (insTerm > 20) baseRate *= 1.5;
      else if (insTerm < 15) baseRate *= 0.8;
      if (insHealth === 'poor') baseRate *= 1.5;
      else if (insHealth === 'excellent') baseRate *= 0.8;
      return { coverage, premium: baseRate };
  }, [insIncome, insYears, insDebt, insHealth, insTerm]);

  const pensionResult = useMemo(() => {
      const rDec = penR / 100;
      const term1 = penP0 * Math.pow((1 + rDec), penN);
      const term2 = rDec > 0 ? penC * ((Math.pow((1 + rDec), penN) - 1) / rDec) : penC * penN;
      const fv = term1 + term2;
      const i = (penDrawI / 100) / 12;
      const payment = i > 0 && penDrawN > 0 ? fv * (i / (1 - Math.pow((1 + i), -penDrawN))) : (penDrawN > 0 ? fv / penDrawN : 0);
      return { fv, payment };
  }, [penP0, penC, penR, penN, penDrawN, penDrawI]);

  const realEstateResult = useMemo(() => {
      const annualRent = reRent * 12;
      const yieldVal = rePrice > 0 ? (annualRent / rePrice) * 100 : 0;
      return { annualRent, yieldVal };
  }, [reRent, rePrice]);

  const roiResult = useMemo(() => {
      const totalInv = roiInitial + roiCosts;
      const netProfit = roiFinal - totalInv;
      const roi = totalInv > 0 ? (netProfit / totalInv) * 100 : 0;
      return { netProfit, roi };
  }, [roiInitial, roiFinal, roiCosts]);

  return (
    <div className="space-y-8 animate-slide-up pb-20">
        <div className="flex justify-between items-end">
            <div>
                <div className="flex items-center gap-3 mb-2">
                    <h2 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                        <TrendingUp className="w-8 h-8 text-emerald-400" />
                        Investment Node
                    </h2>
                    <span className="px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-400 text-[10px] font-black tracking-widest border border-emerald-500/30 shadow-[0_0_10px_rgba(16,185,129,0.2)]">BETA</span>
                </div>
                <p className="text-slate-400 mt-2 font-medium">Portfolio metrics and wealth horizon projection.</p>
            </div>
        </div>

        {/* Wealth Horizon Chart */}
        <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 bg-[#0f172a] relative overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-b from-indigo-500/5 to-transparent pointer-events-none"></div>

            <div className="relative z-10 flex flex-col lg:flex-row justify-between lg:items-end gap-8 mb-8">
                <div>
                    <h3 className="text-xl font-black text-white flex items-center gap-2">
                        <Zap className="w-5 h-5 text-indigo-400" /> Wealth Horizon
                    </h3>
                    <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">30-Year Compounding Projection</p>
                </div>
                <div className="flex flex-wrap gap-6 p-4 bg-slate-900/50 rounded-2xl border border-white/5">
                    <div className="space-y-2">
                        <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Est. Return (APY)</label>
                        <div className="flex items-center gap-3">
                            <input 
                                type="range" min="2" max="15" step="0.5" 
                                value={projRate} onChange={(e) => setProjRate(parseFloat(e.target.value))}
                                className="w-24 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                            />
                            <span className="text-sm font-bold text-white w-10">{projRate}%</span>
                        </div>
                    </div>
                    <div className="space-y-2">
                        <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Monthly Add</label>
                        <div className="flex items-center gap-3">
                            <input 
                                type="range" min="0" max="5000" step="50" 
                                value={projContrib} onChange={(e) => setProjContrib(parseFloat(e.target.value))}
                                className="w-24 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500"
                            />
                            <span className="text-sm font-bold text-white w-16">{formatCurrency(projContrib)}</span>
                        </div>
                    </div>
                </div>
            </div>

            <div className="h-[300px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={projectionData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                        <defs>
                            <linearGradient id="colorWealth" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#6366f1" stopOpacity={0.4}/>
                                <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                            </linearGradient>
                            <linearGradient id="colorInvest" x1="0" y1="0" x2="0" y2="1">
                                <stop offset="5%" stopColor="#10b981" stopOpacity={0.2}/>
                                <stop offset="95%" stopColor="#10b981" stopOpacity={0}/>
                            </linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                        <XAxis dataKey="year" stroke="#64748b" fontSize={10} tickLine={false} axisLine={false} />
                        <YAxis hide />
                        <Tooltip 
                            contentStyle={{ backgroundColor: '#0f172a', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }}
                            itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                            formatter={(val: number, name: string) => [formatCurrency(val), name === 'value' ? 'Projected Value' : 'Principal Invested']}
                            labelStyle={{ color: '#94a3b8', fontSize: '10px', fontWeight: 'bold', textTransform: 'uppercase' }}
                        />
                        <Area type="monotone" dataKey="value" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorWealth)" />
                        <Area type="monotone" dataKey="invested" stroke="#10b981" strokeWidth={2} strokeDasharray="5 5" fillOpacity={1} fill="url(#colorInvest)" />
                    </AreaChart>
                </ResponsiveContainer>
            </div>

            <div className="mt-4 flex justify-between items-center px-2">
                <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                    Current: <span className="text-white">{formatCurrency(totalPortfolioValue)}</span>
                </div>
                <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                    Projected (30y): <span className="text-emerald-400 text-sm">{formatCurrency(projectionData[projectionData.length-1].value)}</span>
                </div>
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Allocation Donut */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 flex flex-col h-[420px]">
                <h3 className="text-lg font-bold text-white flex items-center gap-2 mb-2">
                    <PieChartIcon className="w-5 h-5 text-purple-400" /> Allocation
                </h3>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-6">Distribution by Asset</p>

                <div className="flex-1 min-h-0 relative">
                    {allocationData.length > 0 ? (
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={allocationData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={70}
                                    outerRadius={100}
                                    paddingAngle={5}
                                    dataKey="value"
                                    stroke="none"
                                >
                                    {allocationData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }}
                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                                    formatter={(val: number) => formatCurrency(val)}
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    ) : (
                        <div className="absolute inset-0 flex flex-col items-center justify-center text-center opacity-50">
                            <div className="w-16 h-16 rounded-full bg-slate-800 flex items-center justify-center mb-3">
                                <PieChartIcon className="w-8 h-8 text-slate-500" />
                            </div>
                            <p className="text-xs font-bold text-slate-500 uppercase">No Investment Accounts</p>
                        </div>
                    )}
                </div>

                {/* Legend */}
                <div className="mt-4 flex flex-wrap justify-center gap-3">
                    {allocationData.slice(0, 4).map((entry, index) => (
                        <div key={index} className="flex items-center gap-1.5">
                            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[index % COLORS.length] }}></div>
                            <span className="text-[9px] font-bold text-slate-400 uppercase">{entry.name}</span>
                        </div>
                    ))}
                </div>
            </div>

            {/* Asset Cards Grid (Replaces List) */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 h-[420px] flex flex-col bg-slate-900/40">
                <div className="flex justify-between items-center mb-6">
                    <div>
                        <h3 className="text-lg font-bold text-white flex items-center gap-2"><Target className="w-5 h-5 text-amber-400" /> Holdings</h3>
