import React, { useMemo, useState, useEffect } from 'react';
import { ComposedChart, Line, Area, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, XAxis, YAxis } from 'recharts';
import { Account, Transaction, TransactionType, Category, UserPlan, Goal, Budget, SpendingStatus, SpendingPeriod, Currency } from '../types';
import { Flame, Wallet, CreditCard, Target, Zap, Microscope, FileText, ChevronDown, AlignLeft, GitFork, UserCircle, PieChart as PieChartIcon, TrendingUp, AlertCircle, Check, Plus, Rocket, BarChart3, Clock, Shield, Handshake, Gauge, ArrowUp, CalendarClock, CheckCircle2, ArrowUpRight, ArrowDownLeft, MoreHorizontal, Activity, TrendingDown, Eye, EyeOff, Calendar, Sparkles, Edit2, Trash2 } from 'lucide-react';
import { AddTransactionModal } from './Transactions'; // Import Modal

interface DashboardProps {
