      <svg className="w-full h-full transform -rotate-90">
        {/* Background Circle */}
        <circle cx="16" cy="16" r={radius} stroke="#1e293b" strokeWidth="3" fill="transparent" />
        {/* Progress Circle */}
        <circle 
          cx="16" 
          cy="16" 
